CREATE TABLE contact_message (id UUID PRIMARY KEY, name VARCHAR(150) NOT NULL, email VARCHAR(200) NOT NULL, message VARCHAR(5000) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE invoice (id UUID PRIMARY KEY, client VARCHAR(150) NOT NULL, email VARCHAR(200) NOT NULL, description VARCHAR(500) NOT NULL, quantity NUMERIC(12,2) NOT NULL CHECK (quantity > 0), rate NUMERIC(14,2) NOT NULL CHECK (rate >= 0), currency VARCHAR(3) NOT NULL, total NUMERIC(20,2) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
